'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const safeURL=v=>{try{if(typeof v!=='string'||!v.trim())return '';let value=v.trim();if(value.startsWith('www.'))value='https://'+value;const local=/^(assets|vendor)\//.test(value)||value.startsWith('/');const u=local?new URL(value,location.origin):new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const RECORDS=DIRECTORY.records,RECORD_BY_ID=new Map(RECORDS.map(p=>[p.id,p]));
const CATEGORIES=[...new Set([...(DIRECTORY.categories||[]).map(c=>c.name),...RECORDS.flatMap(p=>p.categories||[p.category])].filter(Boolean))].sort();
const inCategory=(p,category)=>(p.categories||[p.category]).includes(category);
const SPECIALTIES=[...new Set(RECORDS.flatMap(p=>p.specialties))].sort();
const REGIONS=[...new Set(RECORDS.map(p=>p.region).filter(r=>r&&r!=='ALL'))].sort();
const SOURCE_LINKS={home:'https://ujimahealthconnect.com/',about:'https://ujimahealthconnect.com/pages/about-us/',contact:'https://ujimahealthconnect.com/pages/contact/',providers:'https://ujimahealthconnect.com/listings/create/',pricing:'https://ujimahealthconnect.com/pricing/',privacy:'https://ujimahealthconnect.com/pages/privacy-policy/',terms:'https://ujimahealthconnect.com/pages/terms-of-use/',newsletter:'https://ujimahealthconnect.kit.com/1be3b9388e',instagram:'https://www.instagram.com/ujimahealthconnect/'};
const KEY='medconnect-directory-v1';
let db={name:'',location:'North Carolina',saved:[],visits:[],preferences:{},largeText:false},storageOK=true;
try{const existing=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('ujima-real-directory-v1')||'null');if(existing&&typeof existing==='object')db={...db,...existing};else{const old=JSON.parse(localStorage.getItem('ujima-health-connect-v1')||'null');if(old){db.name=old.profile?.name||'';if(old.location&&!/riverton|00000/i.test(old.location))db.location=old.location;db.largeText=!!old.largeText;}}}catch{storageOK=false;}
db.saved=Array.isArray(db.saved)?db.saved.filter(id=>RECORD_BY_ID.has(id)):[];db.visits=Array.isArray(db.visits)?db.visits:[];db.preferences=db.preferences&&typeof db.preferences==='object'?db.preferences:{};
let page='home',profileTab='saved',visibleCount=24,mapView='map',mapQuery='',mapCategory='',mapLimit=18,mapInstance=null,mapLayers=null,installPrompt=null,offlineReady=false,toastTimer;
const defaultFilters=()=>({q:'',location:db.location||'North Carolina',category:'',specialty:'',region:'',language:'',insurance:'',coverage:'',radius:'50',virtualOnly:false,includeVirtual:true,withPhoto:false,verified:false,letter:'',sort:'featured'});
let filters={...defaultFilters(),...db.preferences,location:db.location||'North Carolina'};
const main=$('#main'),modal=$('#modal');
const authState={user:null,ready:false,available:false,mode:'signin',message:'',messageType:'status',busy:false};
const nav=[['home','home','Home'],['care','care','Find care'],['map','map','Resource map'],['community','people','Community'],['profile','user','My care']];
const cityGroups=new Map();
for(const p of NC_GEOGRAPHY.places){const key=normalize(p.name);if(!cityGroups.has(key))cityGroups.set(key,[]);cityGroups.get(key).push(p);}
const CITY_OPTIONS=[...cityGroups.values()].map(rows=>({name:rows[0].name,lat:rows.reduce((n,p)=>n+p.lat,0)/rows.length,lng:rows.reduce((n,p)=>n+p.lng,0)/rows.length})).sort((a,b)=>a.name.localeCompare(b.name));
function resolveLocation(value){const raw=String(value||'').trim(),key=normalize(raw).replace(/,?\s+(nc|north carolina|usa|united states)$/,'').trim();if(!key||['north carolina','nc','all','statewide'].includes(key))return {statewide:true,label:'North Carolina'};const zip=raw.match(/^\s*(\d{5})(?:-\d{4})?\s*$/);if(zip){const p=NC_GEOGRAPHY.places.find(p=>p.zip===zip[1]);return p?{lat:p.lat,lng:p.lng,label:`${p.name}, NC ${p.zip}`,statewide:false}:null;}const city=CITY_OPTIONS.find(p=>normalize(p.name)===key);if(city)return {...city,label:`${city.name}, NC`,statewide:false};return null;}
function miles(a,b){if(!a||a.statewide||!b)return null;const rad=Math.PI/180,dlat=(b[0]-a.lat)*rad,dlon=(b[1]-a.lng)*rad;const v=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b[0]*rad)*Math.sin(dlon/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(v),Math.sqrt(1-v));}
function distanceText(p,origin=resolveLocation(filters.location)){if(p.locationPrecision==='area')return (p.location||'Published location')+' · approximate area';const distance=miles(origin,p.coordinates);return distance===null?null:`${distance<10?distance.toFixed(1):Math.round(distance)} mi straight-line`;}
function isVirtualListing(p){return /virtual|telehealth|online/i.test(p.location)&&p.virtual!==false;}
function acceptedCoverage(p){const value=normalize(p.insurance);if(!value)return 'unknown';if(/^(no|none|n\/a)$|not accept|self[- ]?pay only|private pay only/.test(value))return 'self-pay';if(value==='yes'||/medicaid|medicare|aetna|cigna|blue|united|insurance|humana|tricare|optum/.test(value))return 'accepted';return 'unknown';}
function providerMatches(criteria=filters){const origin=resolveLocation(criteria.location),terms=normalize(criteria.q).split(/\s+/).filter(Boolean);if(!origin)return [];const results=RECORDS.filter(p=>{
 const haystack=normalize([p.name,p.credentials,p.role,p.organization,p.category,...p.specialties,p.location,p.address,p.citiesServed,p.languages,p.insurance].join(' '));
 if(!terms.every(t=>haystack.includes(t)))return false;
 if(criteria.category&&!inCategory(p,criteria.category))return false;if(criteria.specialty&&!p.specialties.includes(criteria.specialty))return false;
 if(criteria.region&&p.region!==criteria.region&&!(criteria.includeVirtual&&p.virtual===true&&p.region==='ALL'))return false;
 if(criteria.language&&!normalize(p.languages).includes(normalize(criteria.language)))return false;
 if(criteria.insurance&&!normalize(p.insurance).includes(normalize(criteria.insurance)))return false;
 if(criteria.coverage&&acceptedCoverage(p)!==criteria.coverage)return false;if(criteria.virtualOnly&&p.virtual!==true)return false;
 if(criteria.withPhoto&&!p.photo)return false;if(criteria.verified&&!p.directoryVerified)return false;
 if(criteria.letter&&normalize(p.name)[0]!==criteria.letter.toLowerCase())return false;
 if(!origin.statewide){const distance=miles(origin,p.coordinates);const virtualMatch=criteria.includeVirtual&&p.virtual===true;if(!virtualMatch&&(distance===null||distance>Number(criteria.radius)))return false;}
 return true;
 });
 return results.sort((a,b)=>{if(criteria.sort==='nearest'&&!origin.statewide){const da=a.locationPrecision==='street'?(miles(origin,a.coordinates)??Infinity):Infinity,db=b.locationPrecision==='street'?(miles(origin,b.coordinates)??Infinity):Infinity;if(da!==db)return da-db;}if(criteria.sort==='featured'){if(a.featured!==b.featured)return Number(b.featured)-Number(a.featured);if(a.directoryVerified!==b.directoryVerified)return Number(b.directoryVerified)-Number(a.directoryVerified);}return a.name.localeCompare(b.name);});}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{storageOK=false;toast('Browser storage is unavailable. Changes will last for this session.');}updateShell();}
function updateShell(){document.body.dataset.page=page;document.body.classList.toggle('large-text',db.largeText);$('#location-name').textContent=db.location==='North Carolina'?'North Carolina':db.location;for(const[target,mobile]of[['#desktop-nav',false],['#mobile-nav',true]])$(target).innerHTML=nav.map(([id,i,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${mobile&&id==='map'?'Map':label}${id==='profile'&&db.saved.length?'<span class="nav-dot"></span>':''}</a>`).join('');}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function link(url,label,classes='text-btn',i='external'){const safe=safeURL(url);return safe?`<a href="${esc(safe)}" target="_blank" rel="noopener noreferrer" class="${classes}">${label}${i?icon(i):''}</a>`:'';}
function phoneLink(p,classes='btn primary'){const digits=String(p.phone||'').replace(/[^+\d]/g,'');return digits.length>=7?`<a href="tel:${esc(digits)}" class="${classes}">${icon('phone')}Call office</a>`:'';}
function emailLink(p,classes='btn secondary'){const email=String(p.email||'').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0];return email?`<a href="mailto:${esc(email)}" class="${classes}">${icon('mail')}Email office</a>`:'';}
function directionsURL(p){if(!p.address||isVirtualListing(p))return '';return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.address)}`;}
function initials(name){return String(name).split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function portrait(p){const photo=safeURL(p.photo);return `<span class="portrait real-portrait"><span class="portrait-initials">${esc(initials(p.name))}</span>${photo?`<img class="provider-photo" src="${esc(photo)}" alt="${esc(p.name)} — provider photo in MedConnect" loading="lazy" decoding="async">`:''}</span>`;}
document.addEventListener('error',e=>{if(e.target.matches?.('img.provider-photo'))e.target.hidden=true;},true);
function notice(text,tone=''){return `<div class="notice ${tone}">${icon('info')}<span>${text}</span></div>`;}
function pageTitle(eyebrow,title,description,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(i,title,text,action=''){return `<div class="empty"><span class="empty-symbol">${icon(i)}</span><h2>${title}</h2><p>${text}</p>${action}</div>`;}
function categoryIcon(name){return /mental|therapy/i.test(name)?'chat':/children|women|wellness/i.test(name)?'heart':/support|navigation/i.test(name)?'people':/research/i.test(name)?'spark':/consult/i.test(name)?'briefcase':'care';}
function providerCard(p){const saved=db.saved.includes(p.id),distance=distanceText(p),cov=p.insurance?`Insurance: ${p.insurance}`:'Confirm insurance with the office';return `<article class="provider-card real-provider-card"><div class="provider-top">${portrait(p)}<div class="provider-heading"><h3>${esc(p.name)}</h3>${p.credentials?`<div class="credentials">${esc(p.credentials)}</div>`:''}<p>${esc(p.specialties.slice(0,2).join(' · ')||p.category||'Healthcare directory listing')}</p></div><button class="save-btn ${saved?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved}">${icon('bookmark')}</button></div><p class="organization-line">${esc(p.organization||p.role||p.location)}</p><div class="provider-meta"><span>${icon('pin')}${esc(distance||p.location||'Location not published')}</span>${p.languages?`<span>${icon('chat')}${esc(p.languages)}</span>`:''}</div><div class="insurance">${icon('shield')}${esc(cov)}</div><div class="card-bottom"><span class="next-time">${p.virtual===true?`${icon('video')} Virtual visits listed`:p.directoryVerified?'Verified in source directory':'MedConnect directory listing'}</span><button class="text-btn" data-action="provider" data-id="${p.id}">View details ${icon('arrow')}</button></div></article>`;}
function sourceNote(){return `<div class="sample-strip">${icon('info')}<span>MedConnect directory data imported ${esc(DIRECTORY.importedAt)} from ${link(SOURCE_LINKS.home,'the original directory','inline-link','')}. Availability, insurance, and office details should be confirmed directly.</span></div>`;}
function home(){const featured=[...(DIRECTORY.featuredOrder||[]).map(id=>RECORD_BY_ID.get(id)).filter(p=>p?.featured&&p.photo),...RECORDS.filter(p=>p.featured&&p.photo)].filter((p,i,rows)=>rows.findIndex(r=>r.id===p.id)===i).slice(0,3),categories=['Primary & Preventative Care','Mental Health & Therapy','Dental Care',"Children's Health"];return `<div class="greeting"><div><div class="eyebrow">YOUR CARE. YOUR COMMUNITY.</div><h1>Hello, ${esc(db.name||'neighbor')}.${icon('sun')}</h1></div><div class="date-note">Connecting North Carolina to care.</div></div><div class="home-grid"><div><section class="hero"><div class="hero-copy"><div class="eyebrow">REAL PEOPLE. REAL CONNECTIONS.</div><h2>Better care.<br><span>Closer to home.</span></h2><p>Discover providers serving Black and underserved communities across North Carolina.</p><a href="#care" class="btn peach">Find my care ${icon('arrow')}</a></div><div class="hero-art" aria-hidden="true"><span class="orbit"></span><span class="orbit two"></span><span class="orbit three"></span><img class="brand-flower" src="brand.svg" alt=""><span class="leaf-bubble">${icon('leaf')}</span><span class="heart-bubble">${icon('heart')}</span><span class="spark"></span></div></section><div class="quick-actions"><a href="#care" class="quick-tile"><span class="tile-icon">${icon('care')}</span><h3>Find care</h3><p>Explore the directory</p></a><button class="quick-tile" data-action="virtual"><span class="tile-icon">${icon('video')}</span><h3>Virtual care</h3><p>Connect from home</p></button><a href="#map" class="quick-tile"><span class="tile-icon">${icon('map')}</span><h3>Street map</h3><p>Real locations</p></a><a href="#community" class="quick-tile"><span class="tile-icon">${icon('people')}</span><h3>Community</h3><p>Stay connected</p></a></div></div><aside class="side-stack"><section class="white-card"><div class="eyebrow">NORTH CAROLINA, CONNECTED</div><span class="small-orbit">${icon('globe')}</span><h3>${RECORDS.length.toLocaleString()} listings.<br>More ways to find care.</h3><p>Search names, practices, specialties, and cities using published information in MedConnect.</p><div class="directory-stats"><span><b>${CATEGORIES.length}</b>categories</span><span><b>${SPECIALTIES.length}</b>specialties</span><span><b>${RECORDS.filter(p=>p.virtual===true).length}</b>virtual listings</span></div><a href="#care" class="text-btn">Explore the directory ${icon('arrow')}</a></section><section class="ride-promo">${icon('route')}<h3>A real route to care.</h3><p>Explore published addresses on the map and open directions.</p><a href="#map" class="text-btn">See the street map <span>↗</span></a></section></aside></div><div class="section-title"><div><h2>Meet the community.</h2><p>Featured providers on MedConnect.</p></div><a href="#care" class="text-btn">See all ${icon('arrow')}</a></div><div class="provider-grid home-providers">${featured.map(providerCard).join('')}</div><div class="section-title"><div><h2>Find your kind of support.</h2><p>Explore care by category.</p></div><button class="text-btn" data-action="all-categories">All categories ${icon('arrow')}</button></div><div class="category-tiles">${categories.filter(c=>CATEGORIES.includes(c)).map(c=>`<button data-category="${esc(c)}" class="category-tile"><span>${icon(categoryIcon(c))}</span><h3>${esc(c)}</h3><small>${RECORDS.filter(p=>inCategory(p,c)).length} listings ${icon('arrow')}</small></button>`).join('')}</div><div class="section-title"><div><h2>Care across North Carolina.</h2><p>Choose a city or search any NC ZIP code.</p></div></div><div class="city-chips">${['Greensboro','Raleigh','Charlotte','Durham','Winston-Salem','Fayetteville','Asheville','Wilmington'].map(city=>`<button class="chip" data-city="${city}">${icon('pin')}${city}</button>`).join('')}</div><section class="join-banner"><div><h3>Help your community find you.</h3><p>Healthcare providers can submit or claim a listing through the original directory.</p></div>${link(SOURCE_LINKS.providers,'List your practice','btn','arrow')}</section>${sourceNote()}`;}
function filterCount(){return ['category','specialty','region','language','insurance','coverage','letter'].filter(k=>filters[k]).length+['virtualOnly','withPhoto','verified'].filter(k=>filters[k]).length;}
function searchBar(id,q,placeholder){return `<form id="${id}" class="search-box" role="search">${icon('search')}<input name="q" aria-label="${id==='care-search'?'Search providers':'Search map listings'}" placeholder="${placeholder}" value="${esc(q)}" maxlength="120"><button class="btn primary" type="submit">Search ${icon('arrow')}</button></form>`;}
function care(){const found=providerMatches(),origin=resolveLocation(filters.location),shown=found.slice(0,visibleCount);return `${pageTitle('CARE ACROSS NORTH CAROLINA','Find your kind of care.','Search real providers, practices, and services with MedConnect.')}<div class="directory-location-row"><button class="chip location-chip" data-action="location">${icon('pin')}${esc(origin?.label||filters.location)} ${icon('chevron')}</button><button class="chip filter-chip" data-action="filters">${icon('filter')}Filters ${filterCount()?`<span class="count-tag">${filterCount()}</span>`:''}</button></div>${searchBar('care-search',filters.q,'Name, specialty, practice, or city')}<div class="filter-row"><button class="chip ${!filters.category?'active':''}" data-category="" aria-pressed="${!filters.category}">All care</button>${['Primary & Preventative Care','Mental Health & Therapy','Dental Care',"Children's Health"].filter(c=>CATEGORIES.includes(c)).map(c=>`<button class="chip ${filters.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${filters.category===c}">${esc(c==='Primary & Preventative Care'?'Primary care':c==='Mental Health & Therapy'?'Mental health':c)}</button>`).join('')}<button class="chip ${filters.virtualOnly?'active':''}" data-action="toggle-virtual" aria-pressed="${filters.virtualOnly}">${icon('video')}Virtual visits</button></div><div class="directory-results-heading"><div><h2>${found.length.toLocaleString()} ${found.length===1?'listing':'listings'}</h2><p>${origin?.statewide?'Across North Carolina':origin?`Within ${filters.radius} miles, plus listed virtual care`:'Location not recognized'}</p></div><label class="sort-control"><span class="sr-only">Sort listings</span><select id="sort-listings" aria-label="Sort listings"><option value="featured" ${filters.sort==='featured'?'selected':''}>Featured first</option><option value="name" ${filters.sort==='name'?'selected':''}>Name A–Z</option><option value="nearest" ${filters.sort==='nearest'?'selected':''}>Nearest first</option></select></label></div><div class="alphabet-row" aria-label="Browse names A to Z"><button data-letter="" class="${!filters.letter?'active':''}">All</button>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<button data-letter="${l}" class="${filters.letter===l?'active':''}">${l}</button>`).join('')}</div>${found.length?`<div class="provider-grid">${shown.map(providerCard).join('')}</div>${shown.length<found.length?`<div class="load-more"><button class="btn secondary" data-action="load-more">Show more listings (${shown.length} of ${found.length}) ${icon('plus')}</button></div>`:''}`:empty('search',origin?'No matching listings found.':'Let’s find your location.',origin?'Try fewer filters or a wider radius. Not every provider publishes insurance or language details.':'Enter a North Carolina city or ZIP code, or explore the entire state.','<button class="btn primary" data-action="reset-filters">Clear filters</button> <button class="btn secondary" data-action="location">Choose location</button>')}${filterCount()||filters.q?'<button class="link-btn" data-action="reset-filters" style="margin-top:18px">Reset all search filters</button>':''}${sourceNote()}`;}
function mapItems(){return providerMatches({...defaultFilters(),q:mapQuery,category:mapCategory,location:db.location,sort:'name'});}
function mappedItems(rows){return rows.filter(p=>p.coordinates&&!isVirtualListing(p));}
function listingRow(p){return `<button class="resource-row" data-action="provider" data-id="${p.id}">${portrait(p)}<span><h3>${esc(p.name)}</h3><p>${esc(p.location||'Location not published')}<br>${esc(p.specialties[0]||p.category||p.organization)}</p></span>${icon('arrow')}</button>`;}
function mapPage(){const found=mapItems(),pins=mappedItems(found);return `${pageTitle('FIND YOUR WAY TO CARE','Real places. Real connections.','Explore published locations on a street map, then open a listing for contact details and directions.')}<div class="directory-location-row"><button class="chip location-chip" data-action="location">${icon('pin')}${esc(db.location)} ${icon('chevron')}</button></div>${searchBar('map-search',mapQuery,'Search providers, practices, or specialties')}<div class="filter-row"><button class="chip ${!mapCategory?'active':''}" data-map-category="">All listings</button>${CATEGORIES.map(c=>`<button class="chip ${mapCategory===c?'active':''}" data-map-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="map-toolbar"><div class="segmented"><button data-map-view="map" class="${mapView==='map'?'active':''}">${icon('map')}Map</button><button data-map-view="list" class="${mapView==='list'?'active':''}">${icon('list')}List</button></div><span class="map-count">${pins.length} mapped · ${found.length} total</span></div>${!found.length?empty('search','No matching locations.','Try another search, choose a different category, or explore the full state.','<button class="btn primary" data-action="reset-map">Reset map search</button>'):mapView==='list'?`<div class="resource-list">${found.slice(0,mapLimit).map(listingRow).join('')}</div>${found.length>mapLimit?'<div class="load-more"><button class="btn secondary" data-action="map-more">Show more listings</button></div>':''}`:`<div class="map-layout real-map-layout"><div class="map-viewport real-map" id="real-map" role="region" aria-label="North Carolina street map with provider locations"></div><div class="map-side">${pins.slice(0,24).map(listingRow).join('')}</div></div><div class="map-legend"><span><i></i>Published street location</span><span><i class="approx"></i>Approximate area</span><button class="text-btn" data-action="fit-map">Show all pins</button></div><p class="map-explanation">${found.length-pins.length} virtual or unmapped ${found.length-pins.length===1?'listing is':'listings are'} available in List view. Pins use Census address-range matches or published coordinates; area-level locations are labeled approximate. Roads and labels are provided by OpenStreetMap.</p>`}<div class="source-attributions">${link('https://www.openstreetmap.org/copyright','© OpenStreetMap contributors','inline-link','')} · ${link('https://www.geonames.org/','City / ZIP data: GeoNames (CC BY 4.0)','inline-link','')} · ${link('https://www.openstreetmap.org/fixthemap','Report a map issue','inline-link','')}</div>${sourceNote()}`;}
function wireMap(){const container=$('#real-map');if(!container)return;if(!globalThis.L){container.innerHTML=empty('map','The map couldn’t load.','You can still browse every listing and open directions from its details.','<button class="btn primary" data-map-view="list">Use list view</button>');return;}
 const origin=resolveLocation(db.location);mapInstance=L.map(container,{scrollWheelZoom:false,zoomControl:true,attributionControl:true}).setView(origin&&!origin.statewide?[origin.lat,origin.lng]:[35.55,-79.5],origin&&!origin.statewide?10:7);
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'}).addTo(mapInstance);
 mapLayers=L.markerClusterGroup?L.markerClusterGroup({maxClusterRadius:42,showCoverageOnHover:false,spiderfyOnMaxZoom:true,iconCreateFunction:cluster=>L.divIcon({html:`<span>${cluster.getChildCount()}</span>`,className:'medconnect-cluster',iconSize:[41,41]})}):L.featureGroup();
 for(const p of mappedItems(mapItems())){const approx=p.locationPrecision!=='street',marker=L.marker(p.coordinates,{title:p.name,alt:p.name,keyboard:true,icon:L.divIcon({className:`real-map-marker ${approx?'area-marker':''}`,html:icon(categoryIcon(p.category)),iconSize:[32,38],iconAnchor:[16,34],popupAnchor:[0,-30]})});
 marker.bindPopup(`<div class="real-map-popup"><strong>${esc(p.name)}</strong><p>${esc(p.address||p.location)}</p>${approx?'<small>Approximate area · precise street location not published</small>':''}<button class="btn primary small" data-action="provider" data-id="${p.id}">View listing ${icon('arrow')}</button></div>`,{maxWidth:280});mapLayers.addLayer(marker);}
 mapInstance.addLayer(mapLayers);if(mapQuery.trim()&&mapLayers.getLayers().length)mapInstance.fitBounds(mapLayers.getBounds(),{padding:[35,35],maxZoom:14});mapInstance.whenReady(()=>mapInstance.invalidateSize());
}
