function openProvider(id){const p=RECORD_BY_ID.get(id);if(!p)return;const seenKeys=new Set(['Clinic/Office Name','Cities Served','Offers Virtual Appointments','Insurance Accepted','Languages','Region']);const other=Object.entries(p.fields).filter(([k])=>!seenKeys.has(k));const updated=p.updated?new Date(p.updated).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):null;
showModal('MEDCONNECT PROVIDER DIRECTORY',esc(p.name),`<div class="detail-provider real-detail-provider">${portrait(p)}<div>${p.directoryVerified?'<span class="status">Verified in source directory</span>':'<span class="status">Public directory listing</span>'}<h3>${esc(p.credentials||p.category||'Healthcare directory')}</h3><p>${esc(p.organization||p.role)}</p></div></div>${p.role?`<p>${esc(p.role)}</p>`:''}<div class="tag-row">${[...(p.categories||[p.category]),...p.specialties].filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="real-contact-actions">${phoneLink(p)}${p.website&&safeURL(p.website)&&!p.website.includes('ujimahealthconnect.com')?link(p.website,'Provider website','btn secondary','external'):''}${emailLink(p)}${p.locationPrecision==='street'&&!isVirtualListing(p)?link(directionsURL(p),'Get directions','btn secondary','route'):''}</div><dl class="detail-list"><dt>Practice</dt><dd>${esc(p.organization||'Not published')}</dd><dt>Location</dt><dd>${esc(p.location||'Not published')}</dd><dt>Address</dt><dd>${esc(p.address||'Street address not published')}${p.locationPrecision==='area'?'<br><small>Map pin represents an approximate area.</small>':''}</dd><dt>Phone</dt><dd>${esc(p.phone||'Not published')}</dd><dt>Email</dt><dd>${esc(p.email||'Not published')}</dd><dt>Insurance</dt><dd>${esc(p.insurance||'Not published — contact the office to confirm')}</dd><dt>Languages</dt><dd>${esc(p.languages||'Not published')}</dd><dt>Virtual visits</dt><dd>${p.virtual===true?'Yes, as listed':p.virtual===false?'No, as listed':'Not published'}</dd><dt>Service area</dt><dd>${esc(p.citiesServed||'Not published')}</dd><dt>Region</dt><dd>${esc(p.region||'Not published')}</dd>${other.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}<dt>Map location</dt><dd>${esc(p.geocodeSource||'Location not available')}</dd><dt>Appointments</dt><dd>Contact the office or use its website for current availability.</dd>${updated?`<dt>Source updated</dt><dd>${updated}</dd>`:''}</dl>${p.socialLinks?.length?`<div class="provider-socials">${p.socialLinks.map((u,i)=>link(u,(()=>{try{return new URL(u).hostname.replace('www.','');}catch{return 'Social profile';}})(),'chip','external')).join('')}</div>`:''}${notice('Office details can change. Confirm insurance, services, accessibility, and appointment availability directly before a visit.')}<div class="dialog-actions"><button class="btn primary" data-action="save-modal" data-id="${p.id}">${icon('bookmark')}${db.saved.includes(p.id)?'Saved to my care':'Save to my care'}</button><button class="btn secondary" data-action="visit" data-id="${p.id}">${icon('calendar')}Add a calendar note</button></div><div class="provider-source">${link(p.source,'View original provider listing','inline-link','external')}<span>Imported ${esc(DIRECTORY.importedAt)}${p.sourcePhoto?' · Photo from the original listing':''}</span></div>`);}
function openVisit(providerId){const p=RECORD_BY_ID.get(providerId);showModal('YOUR PERSONAL VISIT PLANNER','Keep the next step handy.',`<p>Add details for a visit you have arranged, or a reminder to contact a provider. This creates a personal note and calendar file.</p>${notice('This form does not book, request, or confirm a medical appointment. Contact the provider directly to arrange care.')}<form id="visit-form"><div class="field"><label for="visit-provider">Provider / practice</label><select id="visit-provider" name="providerId" required><option value="">Choose a saved or listed provider</option>${[...RECORDS].sort((a,b)=>Number(db.saved.includes(b.id))-Number(db.saved.includes(a.id))||a.name.localeCompare(b.name)).map(r=>`<option value="${r.id}" ${r.id===p?.id?'selected':''}>${esc(r.name)}${r.location?' — '+esc(r.location):''}</option>`).join('')}</select></div><div class="form-row"><div class="field"><label for="visit-date">Date</label><input id="visit-date" name="date" type="date" required></div><div class="field"><label for="visit-time">Time</label><input id="visit-time" name="time" type="time" required></div></div><div class="field"><label for="visit-mode">Type of note</label><select id="visit-mode" name="mode"><option>Visit arranged with the office</option><option>Virtual / phone visit</option><option>Reminder to contact the office</option></select></div><div class="field"><label for="visit-note">Reminder (optional)</label><textarea id="visit-note" name="note" maxlength="500" placeholder="e.g. Call to confirm coverage. Leave out medical details."></textarea></div><div class="form-footer"><button class="btn secondary" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">Save calendar note</button></div></form>`);}
function calendarText(v){const clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=(date,time)=>date.replace(/-/g,'')+'T'+time.replace(/:/g,'')+'00';const start=new Date(v.date+'T'+v.time+':00'),end=new Date(start.getTime()+30*60000),endDate=`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,'0')}-${String(end.getDate()).padStart(2,'0')}`,endTime=`${String(end.getHours()).padStart(2,'0')}:${String(end.getMinutes()).padStart(2,'0')}`;return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//MedConnect//Personal Planner//EN','BEGIN:VEVENT',`UID:${v.id}@medconnect-directory`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${stamp(v.date,v.time)}`,`DTEND:${stamp(endDate,endTime)}`,`SUMMARY:${clean('Care note: '+v.providerName)}`,`LOCATION:${clean(v.location)}`,`DESCRIPTION:${clean('Personal calendar note. This event does not book or confirm an appointment. '+(v.note||''))}`,'END:VEVENT','END:VCALENDAR',''].join('\r\n');}
function downloadCalendar(id){const v=db.visits.find(v=>v.id===id);if(!v)return;const blob=new Blob([calendarText(v)],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`medconnect-care-note-${v.date}.ics`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar event downloaded. Add it to your calendar app.');}
function installDialog(){const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;showModal('YOUR DIRECTORY, IN YOUR POCKET','Take MedConnect with you.',`${standalone?notice('The app is already open in its standalone view.'):''}<p>Add the app to your Home Screen for quick access to the directory and your saved care list.</p>${installPrompt?'<button class="btn primary full" data-action="native-install">'+icon('download')+' Install MedConnect</button>':''}<div class="install-instructions"><span class="step-number">1</span><div><h3>On iPhone</h3><p>Open this link in Safari. Tap Share, then Add to Home Screen.</p></div></div><div class="install-instructions"><span class="step-number">2</span><div><h3>On Android</h3><p>Open this link in Chrome. Use its menu to choose Install app or Add to Home screen.</p></div></div>${notice(offlineReady?'The directory app is cached on this device. Street-map tiles, fresh source pages, and provider websites need internet access.':'Open the app online first. Home Screen installation and offline caching depend on the browser.')}<button class="btn secondary full" data-action="close">Got it</button>`);}
function about(){showModal('SOURCES. SCOPE. YOUR CHOICES.','About MedConnect.',`<p>MedConnect brings together ${RECORDS.length} public provider listings, imported on ${esc(DIRECTORY.importedAt)} with permission to reuse the directory content.</p>${notice('This is a directory and personal organizer. It does not verify your insurance benefits, provide live wait times, or book medical appointments. Each listing links directly to the source and its published contact options.')}<h3>Where the information comes from</h3><p>Names, credentials, practices, photographs, addresses, contact details, and listing fields come from the original provider directory. Source badges describe the directory’s listing status. Fields that were not published are left unconfirmed.</p><p>Street-map roads and labels are provided by OpenStreetMap. Pins use Census address-range matches where possible, published coordinates, or explicitly labeled city-level estimates. City and ZIP centers are from GeoNames and distances are approximate straight-line distances.</p><h3>Your information</h3><p>Your nickname, preferences, saved listings, and calendar notes stay in this browser${storageOK?'':' for this session'}. They are not shared with providers or synchronized across devices. Map tiles load from OpenStreetMap; external links follow those sites’ privacy terms.</p><div class="community-link-list">${link(SOURCE_LINKS.home,'Original provider directory','community-link','external')}${link(SOURCE_LINKS.privacy,'Source directory privacy policy','community-link','external')}${link(SOURCE_LINKS.terms,'Source directory terms of use','community-link','external')}${link('https://www.openstreetmap.org/copyright','OpenStreetMap attribution','community-link','external')}${link('https://www.geonames.org/','GeoNames attribution · CC BY 4.0','community-link','external')}${link('https://geocoding.geo.census.gov/geocoder/','US Census address matching','community-link','external')}</div><p class="tiny muted" style="margin-top:20px">The public directory is a dated import, not an automatic live feed. Open the original listing for the latest information. This app does not provide medical advice.</p>`);}
function setLocation(value){const origin=resolveLocation(value);if(!origin)return false;db.location=origin.statewide?'North Carolina':String(value).trim();filters.location=db.location;if(!origin.statewide&&filters.sort==='featured')filters.sort='nearest';visibleCount=24;mapLimit=18;persist();return true;}
function toggleSave(id,fromModal=false){if(!RECORD_BY_ID.has(id))return;const saved=db.saved.includes(id);db.saved=saved?db.saved.filter(x=>x!==id):[...db.saved,id];persist();render();if(fromModal)openProvider(id);toast(saved?'Listing removed from your saved care list.':'Listing saved in My care.');}
document.addEventListener('click',async e=>{
 const anchor=e.target.closest('a[href^="#"]');if(anchor){e.preventDefault();if(anchor.classList.contains('skip')){main.focus();main.scrollIntoView();}else navigate(anchor.getAttribute('href').slice(1));return;}
 const city=e.target.closest('[data-city]');if(city){setLocation(city.dataset.city);modal.close();navigate('care');return;}
 const category=e.target.closest('[data-category]');if(category){filters.category=category.dataset.category;visibleCount=24;navigate('care');return;}
 const mapCategoryButton=e.target.closest('[data-map-category]');if(mapCategoryButton){mapCategory=mapCategoryButton.dataset.mapCategory;mapLimit=18;render();return;}
 const mapViewButton=e.target.closest('[data-map-view]');if(mapViewButton){mapView=mapViewButton.dataset.mapView;render();return;}
 const letter=e.target.closest('[data-letter]');if(letter){filters.letter=letter.dataset.letter;visibleCount=24;render();return;}
 const tab=e.target.closest('[data-profile-tab]');if(tab){profileTab=tab.dataset.profileTab;render();return;}
 const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;
 switch(b.dataset.action){
 case'close':modal.close();break;case'about':about();break;case'install':installDialog();break;case'native-install':if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;modal.close();}break;
 case'care':modal.close();navigate('care');break;case'profile':modal.close();navigate('profile');break;case'auth-show-signin':authState.mode='signin';authState.message='';renderAuthPanel();break;case'auth-show-signup':authState.mode='signup';authState.message='';renderAuthPanel();break;case'auth-signout':await signOutAuth();break;
 case'location':openLocation();break;case'statewide':setLocation('North Carolina');modal.close();render();break;
 case'filters':case'all-categories':openFilters();break;case'clear-filter-modal':filters=defaultFilters();openFilters();break;
 case'reset-filters':filters=defaultFilters();visibleCount=24;render();break;case'virtual':filters={...defaultFilters(),virtualOnly:true};navigate('care');break;case'toggle-virtual':filters.virtualOnly=!filters.virtualOnly;visibleCount=24;render();break;
 case'provider':openProvider(id);break;case'save':toggleSave(id);break;case'save-modal':toggleSave(id,true);break;
 case'load-more':visibleCount+=24;render();break;case'map-more':mapLimit+=24;render();break;case'reset-map':mapQuery='';mapCategory='';setLocation('North Carolina');render();break;
 case'fit-map':if(mapInstance&&mapLayers?.getLayers().length)mapInstance.fitBounds(mapLayers.getBounds(),{padding:[25,25],maxZoom:13});break;
 case'visit':openVisit(id);break;case'new-visit':openVisit();break;case'calendar':downloadCalendar(id);break;case'remove-visit':db.visits=db.visits.filter(v=>v.id!==id);persist();render();toast('Personal calendar note removed.');break;
 }
});
document.addEventListener('change',e=>{if(e.target.id==='sort-listings'){filters.sort=e.target.value;visibleCount=24;render();}if(e.target.matches('[data-setting="large-text"]')){db.largeText=e.target.checked;persist();}});
document.addEventListener('submit',e=>{
 const form=e.target,accepted=['care-search','map-search','location-form','filter-form','preferences-form','visit-form','auth-signin-form','auth-signup-form'];if(!accepted.includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const f=Object.fromEntries(new FormData(form));for(const key in f)if(typeof f[key]==='string'&&key!=='password')f[key]=f[key].trim();
 switch(form.id){
 case'care-search':filters.q=f.q;visibleCount=24;render();break;case'map-search':mapQuery=f.q;mapLimit=18;render();break;
 case'location-form':if(!setLocation(f.location)){$('#location-error').innerHTML='<div class="error">Choose a North Carolina city or ZIP code, or enter North Carolina for the whole state.</div>';return;}modal.close();render();break;
 case'filter-form':filters={...filters,...f,virtualOnly:!!f.virtualOnly,includeVirtual:!!f.includeVirtual,withPhoto:!!f.withPhoto,verified:!!f.verified};visibleCount=24;modal.close();navigate('care');break;
 case'auth-signin-form':void submitAuthForm('signin',f);break;case'auth-signup-form':void submitAuthForm('signup',f);break;case'preferences-form':if(!setLocation(f.location)){toast('Please choose a valid North Carolina city or ZIP.');return;}db.name=f.name;db.preferences=f.saveFilters?{...filters,q:'',letter:''}:{};persist();render();toast('Preferences saved on this device.');break;
 case'visit-form':{const p=RECORD_BY_ID.get(f.providerId);if(!p||!f.date||!f.time)return;db.visits.unshift({id:uid(),providerId:p.id,providerName:p.name,date:f.date,time:f.time,mode:f.mode,note:f.note||'',location:f.mode==='Virtual / phone visit'?'Virtual / phone visit':p.address||p.location,created:Date.now()});persist();modal.close();profileTab='visits';navigate('profile');toast('Personal calendar note saved. No appointment was booked.');break;}
 }
});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('MedConnect was added to your device.');});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;}).catch(()=>{}));
initializeAuth();
render();
